42	/** Base URLs are API roots, not operation URLs. Preserve custom gateway prefixes. */
43	export function endpoint(base: string, operation: string): string {
44	  let url: URL;
45	  try { url = new URL(base); } catch { throw new ProviderError('Provider base URL must be a valid HTTP or HTTPS URL.'); }
46	  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.search || url.hash)
47	    throw new ProviderError('Provider base URL must use HTTP(S), without credentials, query parameters, or fragments.');
