104	  }
105	  return Number.isFinite(milliseconds) ? Math.min(MAX_RETRY_DELAY_MS, Math.max(0, milliseconds)) : 500 * 2 ** (attempt - 1);
106	}
107	function waitForRetry(delayMs: number, signal?: AbortSignal | null): Promise<void> {
