110	    const timer = setTimeout(() => { signal?.removeEventListener('abort', abort); resolve(); }, delayMs);
111	    const abort = () => { clearTimeout(timer); signal?.removeEventListener('abort', abort); reject(signal?.reason || new DOMException('Request cancelled', 'AbortError')); };
112	    signal?.addEventListener('abort', abort, { once: true });
113	  });
114	}
115	async function request(url: string, init: RequestInit, retry?: { onRetry?: CompletionOptions['onRetry'] }): Promise<Response> {
116	  for (let retries = 0; ; retries++) {
117	    init.signal?.throwIfAborted();
118	    let response: Response;
119	    try { response = await fetch(url, { ...init, redirect: 'error' }); }
120	    catch {
121	      if (init.signal?.aborted) throw init.signal.reason || new DOMException('Request cancelled', 'AbortError');
122	      // A disconnected POST may have been processed and billed. Never automatically replay it.
123	      throw new ProviderError('Cannot reach provider. Check the base URL, network, and TLS configuration. The request was not retried; it may have reached the provider.', { code: 'network_error' });
124	    }
125	    if (response.ok) return response;
126	    let body: any;
127	    try { body = await response.json(); }
128	    catch (error) {
129	      init.signal?.throwIfAborted();
130	      // Non-JSON gateway pages still carry an explicit HTTP status. A disconnected
131	      // body is different: don't replay when an error's quota/type details were lost.
132	      if (!(error instanceof SyntaxError)) throw new ProviderError('Provider error response was interrupted. No automatic retry was attempted.', { status: response.status, code: 'network_error' });
133	    }
134	    init.signal?.throwIfAborted();
135	    const error = httpError(response.status, body);
136	    if (!retry || !error.retryable || retries >= MAX_RETRIES) throw error;
137	    const attempt = retries + 1, delayMs = retryDelay(response.headers.get('retry-after'), attempt);
138	    // The callback carries only numeric local fields, never provider text or credential-bearing data.
139	    retry.onRetry?.({ attempt, delayMs, status: response.status });
140	    await waitForRetry(delayMs, init.signal);
141	  }
142	}
