144	/** Streaming decoder tolerates split UTF-8, CRLF, comments, and multiline data fields. */
145	export async function* parseSSE(response: Response, signal: AbortSignal): AsyncGenerator<{ event: string; data: string }> {
146	  if (!response.body) throw new ProviderError('Provider returned an empty streaming response.');
147	  const reader = response.body.getReader();
148	  const decoder = new TextDecoder();
149	  let buffer = '', event = '', fields: string[] = [], eventSize = 0;
150	  const onAbort = () => { void reader.cancel().catch(() => {}); };
151	  signal.addEventListener('abort', onAbort, { once: true });
152	  function line(value: string): { event: string; data: string } | undefined {
153	    if (value === '') {
154	      const result = fields.length ? { event, data: fields.join('\n') } : undefined;
155	      event = ''; fields = []; eventSize = 0;
156	      return result;
157	    }
158	    if (value.startsWith(':')) return;
159	    const colon = value.indexOf(':');
160	    const key = colon < 0 ? value : value.slice(0, colon);
161	    const raw = colon < 0 ? '' : value.slice(colon + 1);
162	    const content = raw.startsWith(' ') ? raw.slice(1) : raw;
163	    if (key === 'event') event = content;
164	    if (key === 'data') {
165	      eventSize += content.length;
166	      if (eventSize > MAX_EVENT_BYTES) throw new ProviderError('Provider stream event exceeded the size limit.');
167	      fields.push(content);
168	    }
169	  }
170	  try {
171	    while (true) {
172	      signal.throwIfAborted();
173	      const { value, done } = await reader.read();
174	      signal.throwIfAborted();
175	      buffer += decoder.decode(value, { stream: !done });
176	      let offset = 0;
177	      for (let i = 0; i < buffer.length; i++) {
178	        if (buffer[i] !== '\n' && buffer[i] !== '\r') continue;
179	        if (buffer[i] === '\r' && i === buffer.length - 1 && !done) break;
180	        const parsed = line(buffer.slice(offset, i));
181	        if (buffer[i] === '\r' && buffer[i + 1] === '\n') i++;
182	        offset = i + 1;
183	        if (parsed) yield parsed;
184	      }
185	      buffer = buffer.slice(offset);
186	      if (buffer.length > MAX_EVENT_BYTES) throw new ProviderError('Provider stream line exceeded the size limit.');
187	      if (done) {
188	        if (buffer) { const parsed = line(buffer); if (parsed) yield parsed; }
189	        const parsed = line(''); if (parsed) yield parsed;
190	        break;
191	      }
192	    }
193	  } catch (error) {
194	    if (signal.aborted) throw signal.reason || new DOMException('Request cancelled', 'AbortError');
195	    if (error instanceof ProviderError) throw error;
196	    throw new ProviderError('Provider stream connection was interrupted. No automatic retry was attempted.', { code: 'stream_interrupted' });
197	  } finally {
198	    signal.removeEventListener('abort', onAbort);
199	    await reader.cancel().catch(() => {});
200	    reader.releaseLock();
201	  }
202	}
