213	async function* chatStream(response: Response, signal: AbortSignal, scope: { providerId: string; model: string }): AsyncGenerator<StreamChunk> {
214	  let finished = false, reasoningText = '', toolsSeen = false;
215	  const thinkingBlocks: any[] = [], reasoningItems: any[] = [];
216	  const remember = function* (): Generator<StreamChunk> {
217	    if (thinkingBlocks.length || reasoningItems.length || reasoningText) yield { type: 'metadata', metadata: { ...scope,
218	      ...(reasoningText ? { reasoning_content: reasoningText } : {}),
219	      ...(thinkingBlocks.length ? { thinking_blocks: thinkingBlocks } : {}),
220	      ...(reasoningItems.length ? { reasoning_items: reasoningItems } : {}),
221	    } };
222	  };
223	  for await (const { data } of parseSSE(response, signal)) {
224	    if (data.trim() === '[DONE]') { if (!toolsSeen) finished = true; break; }
225	    const chunk = jsonEvent(data);
226	    if (chunk.error) throw streamError(chunk);
227	    if (chunk.usage) yield { type: 'usage', usage: usage(chunk.usage) };
228	    // n is always one; don't combine unrelated alternatives into one assistant message.
229	    const choice = chunk.choices?.find((c: any) => (c.index ?? 0) === 0);
230	    if (!choice) continue;
231	    const delta = choice.delta || {};
232	    if (typeof delta.content === 'string' && delta.content) yield { type: 'text', text: delta.content };
233	    const reasoning = delta.reasoning_content ?? delta.reasoning;
234	    if (typeof reasoning === 'string' && reasoning) { reasoningText += reasoning; yield { type: 'reasoning', text: reasoning }; }
235	    // LiteLLM emits unsigned thinking fragments followed by a complete signed block.
236	    // Only signed blocks (and opaque redacted blocks) are safe to replay.
237	    for (const block of delta.thinking_blocks || delta.provider_specific_fields?.thinking_blocks || []) {
238	      if ((block.type === 'thinking' && typeof block.signature === 'string') || block.type === 'redacted_thinking') {
239	        if (!thinkingBlocks.some(existing => JSON.stringify(existing) === JSON.stringify(block))) thinkingBlocks.push(block);
240	      }
241	    }
242	    for (const item of delta.reasoning_items || []) if (!reasoningItems.some(existing => JSON.stringify(existing) === JSON.stringify(item))) reasoningItems.push(item);
243	    if (Array.isArray(delta.tool_calls)) for (const call of delta.tool_calls) {
244	      toolsSeen = true;
245	      if (!Number.isInteger(call.index) || call.index < 0) throw new ProviderError('Provider returned a tool call without a valid stream index.');
246	      yield { type: 'tool', tool: {
247	        index: call.index, id: call.id, name: call.function?.name, arguments: call.function?.arguments,
248	      } };
249	    }
250	    if (choice.finish_reason) {
251	      if (choice.finish_reason === 'length') throw new ProviderError('The model reached its output limit. No partial tool calls were executed.');
252	      if (choice.finish_reason === 'content_filter') throw new ProviderError('The provider stopped the response because of content filtering.');
253	      finished = true;
254	    }
255	  }
256	  if (!finished) throw new ProviderError('Provider stream ended before completion. No partial tool calls were executed.');
257	  yield* remember();
258	}
