202	    descriptor = openSync(target, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
203	    const before = fstatSync(descriptor), linked = lstatSync(target);
204	    if (linked.isSymbolicLink() || linked.dev !== before.dev || linked.ino !== before.ino || !before.isFile() || before.nlink !== 1 || before.size > 64 * 1024) return ignored;
