350	/** Resolve every existing component, including ancestors of a not-yet-created file. */
351	export async function resolveWorkspacePath(workspace: string, filePath: string, options: { allowMissing?: boolean; allowOutside?: boolean } = {}): Promise<string> {
352	  if (typeof workspace !== 'string' || !workspace || typeof filePath !== 'string' || filePath.includes('\0')) throw new Error('Invalid workspace path.');
353	  const lexicalRoot = path.resolve(workspace);
354	  const root = await fs.realpath(lexicalRoot);
355	  if (!(await fs.stat(root)).isDirectory()) throw new Error('Workspace must be a directory.');
356	  const candidate = path.resolve(lexicalRoot, filePath);
357	  const base = within(lexicalRoot, candidate) ? lexicalRoot : within(root, candidate) ? root : options.allowOutside ? path.parse(candidate).root : root;
358	  if (!within(base, candidate)) throw new Error('Path is outside the workspace.');
359	  const parts = path.relative(base, candidate).split(path.sep).filter(Boolean);
360	  let current = base === lexicalRoot ? root : base;
361	  for (let index = 0; index < parts.length; index++) {
362	    current = path.join(current, parts[index]);
363	    try {
364	      const entry = await fs.lstat(current);
365	      // A dangling symlink is not a missing file: resolving it must fail.
366	      const resolved = await fs.realpath(current);
367	      if (!options.allowOutside && !within(root, resolved)) throw new Error('Symlink points outside the workspace.');
368	      if (index < parts.length - 1 && !(entry.isDirectory() || (entry.isSymbolicLink() && (await fs.stat(resolved)).isDirectory()))) throw new Error('A parent path is not a directory.');
369	      current = resolved;
370	    } catch (error) {
371	      if (options.allowMissing && hasCode(error, 'ENOENT')) {
372	        // lstat detects a dangling link, even when realpath failed with ENOENT.
373	        const existing = await fs.lstat(current).catch(e => { if (hasCode(e, 'ENOENT')) return null; throw e; });
374	        if (existing) throw new Error('Cannot resolve a dangling symlink.');
375	        return path.join(current, ...parts.slice(index + 1));
376	      }
377	      throw error;
378	    }
379	  }
380	  return current;
381	}
