440	async function readAbsoluteText(absolute: string, maxBytes: number, complete = false): Promise<{ absolute: string; content: string; truncated: boolean }> {
441	  // O_NONBLOCK avoids hanging on FIFOs; O_NOFOLLOW catches last-component swaps.
442	  const handle = await fs.open(absolute, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
443	  try {
444	    const stat = await handle.stat();
445	    if (!stat.isFile()) throw new Error('Path is not a regular file.');
446	    if (stat.nlink > 1) throw new Error('Hard-linked files cannot be read safely because their aliases may contain protected credentials.');
447	    if (complete && stat.size > maxBytes) throw new Error(`File is too large to edit safely (maximum ${maxBytes} bytes).`);
448	    const buffer = Buffer.alloc(maxBytes + 1);
449	    let length = 0;
450	    while (length < buffer.length) {
451	      const { bytesRead } = await handle.read(buffer, length, buffer.length - length, null);
452	      if (!bytesRead) break;
453	      length += bytesRead;
454	    }
455	    const truncated = length > maxBytes;
456	    if (complete && truncated) throw new Error('File grew beyond the safe editing limit.');
457	    const bytes = buffer.subarray(0, Math.min(length, maxBytes));
458	    if (bytes.includes(0)) throw new Error('Binary files are not supported; select a UTF-8 text file.');
459	    let content: string;
460	    try { content = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes, { stream: truncated }); }
461	    catch { throw new Error('File is binary or is not valid UTF-8 text.'); }
462	    const controls = content.match(/[\x01-\x08\x0b\x0e-\x1f]/g)?.length ?? 0;
463	    if (controls > Math.max(2, content.length / 100)) throw new Error('Binary files are not supported.');
464	    return { absolute, content, truncated };
465	  } finally { await handle.close(); }
466	}
