166	    let descriptor: number | undefined;
167	    try {
168	      const target = path.join(root, file), parent = path.dirname(target);
169	      if (parent !== root && (lstatSync(parent).isSymbolicLink() || realpathSync(parent) !== parent)) continue;
170	      if (realpathSync(target) !== target) continue;
171	      descriptor = openSync(target, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
172	      const before = fstatSync(descriptor);
173	      const linked=lstatSync(target);
174	      if(realpathSync(root)!==root||realpathSync(parent)!==parent||realpathSync(target)!==target||linked.isSymbolicLink()||linked.dev!==before.dev||linked.ino!==before.ino)continue;
175	      if (!before.isFile() || before.nlink !== 1 || before.size > READ_LIMIT) continue;
176	      const bytes = Buffer.alloc(Math.min(before.size, READ_LIMIT));
177	      const count = readSync(descriptor, bytes, 0, bytes.length, 0), after = fstatSync(descriptor);
178	      const finalLink=lstatSync(target);
179	      if (count !== before.size || after.size !== before.size || after.mtimeMs !== before.mtimeMs || after.ctimeMs !== before.ctimeMs || after.nlink !== 1 || after.dev !== before.dev || after.ino !== before.ino || finalLink.isSymbolicLink() || finalLink.dev !== before.dev || finalLink.ino !== before.ino || realpathSync(root) !== root || realpathSync(parent) !== parent || realpathSync(target) !== target) continue;
180	      const content = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
181	      if (content.includes('\0')) continue;
182	      result += `\n\nProject instructions (${file}):\n${content.slice(0, 24000)}`;
183	    } catch { /* Optional guidance must never open unsafe special files. */ }
184	    finally { if (descriptor !== undefined) closeSync(descriptor); }
185	  }
186	  return result;
187	}
